    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id               String           @id @default(cuid())\n  email            String?          @unique\n  name             String?\n  firstName        String?\n  lastName         String?\n  nickname         String?          @unique\n  isDefault        Boolean          @default(true)\n  image            String?\n  emailVerified    DateTime?\n  monetizationRole MonetizationRole @default(FREE)\n  workRole         WorkRole         @default(CLIENT)\n  ownedBoards      Board[]          @relation(\"BoardOwner\")\n  boardMemberships BoardMember[]\n  accounts         Account[]\n  comments         Comment[]\n  notifications    Notification[]\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n}\n\nmodel Board {\n  id          String  @id @default(cuid())\n  title       String\n  description String?\n  logoUrl     String?\n  themeColor  String?\n\n  ownerId String?\n  owner   User?   @relation(\"BoardOwner\", fields: [ownerId], references: [id])\n\n  tickets       Ticket[]\n  columns       BoardColumn[]\n  memberships   BoardMember[]\n  roles         BoardRole[]\n  invitations   BoardInvitation[]\n  notifications Notification[]\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n}\n\nmodel BoardMember {\n  id           String          @id @default(cuid())\n  role         BoardMemberRole @default(MEMBER)\n  boardId      String\n  userId       String\n  customRoleId String?\n  board        Board           @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  user         User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  customRole   BoardRole?      @relation(fields: [customRoleId], references: [id], onDelete: SetNull)\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@unique([boardId, userId])\n  @@index([userId])\n}\n\nmodel BoardRole {\n  id          String        @id @default(cuid())\n  boardId     String\n  board       Board         @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  name        String\n  permissions String[]      @default([])\n  members     BoardMember[]\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  @@unique([boardId, name])\n  @@index([boardId])\n}\n\nmodel BoardInvitation {\n  id              String         @id @default(cuid())\n  token           String         @unique // URL-safe token for public invitation link\n  type            InvitationType @default(PERSONAL)\n  email           String?\n  boardId         String\n  board           Board          @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  customRoleId    String?\n  customRoleName  String?\n  createdByUserId String?\n  status          String         @default(\"pending\") // \"pending\" | \"accepted\" | \"declined\"\n  maxUses         Int            @default(1)\n  usedCount       Int            @default(0)\n  expiresAt       DateTime\n  createdAt       DateTime       @default(now())\n\n  @@index([boardId])\n  @@index([email])\n  @@index([token])\n  @@index([boardId, type])\n  @@index([customRoleId])\n  @@index([createdByUserId])\n}\n\nmodel BoardColumn {\n  id       String @id @default(cuid())\n  title    String\n  position Int\n\n  boardId String\n  board   Board    @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tickets Ticket[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([boardId, position])\n}\n\nmodel Ticket {\n  id String @id\n\n  title       String\n  description String?\n\n  status    String\n  sortIndex Int    @default(0)\n  priority  String\n  type      String\n\n  accessPolicy Json @default(\"{\\\"view\\\":[],\\\"edit\\\":[],\\\"delete\\\":[],\\\"estimate\\\":[],\\\"comment\\\":[],\\\"manageAccess\\\": []}\")\n\n  boardId String\n  board   Board  @relation(fields: [boardId], references: [id], onDelete: Cascade)\n\n  columnId String?\n  column   BoardColumn? @relation(fields: [columnId], references: [id], onDelete: SetNull)\n\n  estimateOriginalHours  Int?\n  estimateSpentHours     Int?\n  estimateRemainingHours Int?\n  storyPoints            Int?\n\n  subtasks      Subtask[]\n  comments      Comment[]\n  notifications Notification[]\n\n  dueDate   DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([boardId, status, sortIndex])\n  @@index([boardId, columnId, sortIndex])\n}\n\nmodel Subtask {\n  id       String  @id @default(cuid())\n  title    String\n  done     Boolean @default(false)\n  ticketId String\n  ticket   Ticket  @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n}\n\nmodel Comment {\n  id        String   @id @default(cuid())\n  body      String\n  ticketId  String\n  ticket    Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  authorId  String?\n  author    User?    @relation(fields: [authorId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Notification {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  boardId   String\n  board     Board     @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  ticketId  String?\n  ticket    Ticket?   @relation(fields: [ticketId], references: [id], onDelete: SetNull)\n  kind      String\n  title     String\n  message   String\n  isRead    Boolean   @default(false)\n  readAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId, createdAt])\n  @@index([userId, isRead])\n  @@index([boardId])\n  @@index([ticketId])\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nenum BoardMemberRole {\n  OWNER\n  ADMIN\n  MEMBER\n  VIEWER\n}\n\nenum InvitationType {\n  PERSONAL\n  SHARED\n}\n\nenum MonetizationRole {\n  FREE\n  SUBMITTED\n  PREMIUM\n}\n\nenum WorkRole {\n  CLIENT\n  EXECUTOR\n  ORGANIZER\n  CEO\n}\n",
